<template>
  <IframeViewer
    :entry="entry"
    @create-editor="emit('create-editor')"
    @exit-editor="handleExitEditor"
    @activated-change="handleActivatedChange"
  />
</template>

<script setup lang="ts">
import { computed } from 'vue';
import { useRoute } from 'vue-router';

import IframeViewer from '../components/IframeViewer.vue';
import { useEditorsStore } from '../store/editors';

const emit = defineEmits<{
  (event: 'create-editor'): void;
  (event: 'exit-editor', id: string): void;
  (event: 'activated-change', ids: string[]): void;
}>();

const route = useRoute();
const store = useEditorsStore();

const entry = computed(() => {
  const id = typeof route.params.id === 'string' ? route.params.id : '';
  return store.findEntry(id);
});

function handleExitEditor(id: string) {
  emit('exit-editor', id);
}

function handleActivatedChange(ids: string[]) {
  emit('activated-change', ids);
}
</script>
