<template>
  <article
    class="group relative cursor-pointer rounded-2xl border p-3 transition duration-150 hover:-translate-y-px hover:shadow-card"
    :class="active ? 'border-navigator-blue/30 bg-white shadow-card' : 'border-white/70 bg-white/55 hover:bg-white/90'"
    @click="$emit('navigate', entry)"
  >
    <div v-if="active" class="absolute left-0 top-4 h-10 w-1 rounded-r-full bg-navigator-blue" />
    <div class="flex items-start gap-3">
      <div
        class="flex size-10 shrink-0 items-center justify-center rounded-2xl bg-gradient-to-br from-slate-50 to-blue-50 text-xl shadow-sm"
      >
        {{ entry.icon || '🛠️' }}
      </div>
      <div class="min-w-0 flex-1">
        <div class="flex items-start gap-2">
          <h3 class="min-w-0 flex-1 truncate text-sm font-semibold leading-5 text-slate-900" :title="entry.name">
            {{ entry.name }}
          </h3>
          <span
            v-if="activated"
            class="mt-1 inline-block size-2 shrink-0 rounded-sm bg-emerald-500"
            title="iframe 已激活"
          ></span>
          <span
            v-if="entry.openMode === 'external'"
            class="shrink-0 rounded-full bg-amber-50 px-2 py-0.5 text-[10px] font-medium text-amber-600"
            >外链</span
          >
          <span
            v-if="entry.builtin"
            class="shrink-0 rounded-full bg-blue-50 px-2 py-0.5 text-[10px] font-medium text-navigator-blue"
            >内置</span
          >
        </div>
        <p class="mt-1 line-clamp-2 text-xs leading-5 text-slate-500">{{ entry.description || entry.url }}</p>
      </div>
    </div>

    <div class="mt-3 flex items-center justify-between gap-2 text-[11px] text-slate-400">
      <span class="truncate">{{ entry.url }}</span>
      <div class="flex shrink-0 items-center gap-1 opacity-0 transition group-hover:opacity-100">
        <button
          class="rounded-lg p-1.5 text-slate-500 hover:bg-slate-100 hover:text-navigator-blue disabled:cursor-not-allowed disabled:opacity-35"
          type="button"
          title="上移"
          :disabled="!canMoveUp"
          @click.stop="$emit('move-up', entry)"
        >
          <ChevronUp class="size-3.5" />
        </button>
        <button
          class="rounded-lg p-1.5 text-slate-500 hover:bg-slate-100 hover:text-navigator-blue disabled:cursor-not-allowed disabled:opacity-35"
          type="button"
          title="下移"
          :disabled="!canMoveDown"
          @click.stop="$emit('move-down', entry)"
        >
          <ChevronDown class="size-3.5" />
        </button>
        <button
          class="rounded-lg p-1.5 text-slate-500 hover:bg-slate-100 hover:text-navigator-blue"
          type="button"
          title="编辑"
          @click.stop="$emit('edit', entry)"
        >
          <Pencil class="size-3.5" />
        </button>
        <button
          class="rounded-lg p-1.5 text-slate-500 hover:bg-red-50 hover:text-red-500"
          type="button"
          :title="entry.builtin ? '隐藏内置项' : '删除'"
          @click.stop="$emit('remove', entry)"
        >
          <Trash2 class="size-3.5" />
        </button>
      </div>
    </div>
  </article>
</template>

<script setup lang="ts">
import { ChevronDown, ChevronUp, Pencil, Trash2 } from 'lucide-vue-next';

import type { EditorEntry } from '../types/editor-entry';

defineProps<{
  entry: EditorEntry;
  active: boolean;
  activated: boolean;
  canMoveUp: boolean;
  canMoveDown: boolean;
}>();

defineEmits<{
  navigate: [entry: EditorEntry];
  edit: [entry: EditorEntry];
  remove: [entry: EditorEntry];
  'move-up': [entry: EditorEntry];
  'move-down': [entry: EditorEntry];
}>();
</script>
