export interface UrlValidationResult {
  valid: boolean;
  value: string;
  message?: string;
}

const HTTP_URL_PATTERN = /^https?:\/\//i;

export function validateEditorUrl(rawUrl: string): UrlValidationResult {
  const value = rawUrl.trim();

  if (!value) {
    return { valid: false, value, message: '请输入编辑器页面 URL。' };
  }

  if (!HTTP_URL_PATTERN.test(value)) {
    return { valid: false, value, message: '仅支持 http 或 https 页面，不能使用 javascript/data 协议。' };
  }

  if (typeof URL.canParse === 'function' && !URL.canParse(value)) {
    return { valid: false, value, message: 'URL 格式不正确，请检查协议、域名与路径。' };
  }

  const parsedUrl = new URL(value);
  if (parsedUrl.protocol !== 'http:' && parsedUrl.protocol !== 'https:') {
    return { valid: false, value, message: '仅支持 http 或 https 页面。' };
  }

  return { valid: true, value: parsedUrl.toString() };
}

export function isValidEditorUrl(rawUrl: string): boolean {
  return validateEditorUrl(rawUrl).valid;
}
