<template>
  <div class="flex h-full min-h-0 flex-col text-slate-800">
    <AppHeader
      :can-export="store.visibleCount > 0"
      @create="openCreateDialog"
      @import="openImportDialog"
      @export="exportConfig"
      @restore-default="restoreDefaultConfig"
    />

    <main class="flex min-h-0 flex-1 pt-14 max-[960px]:flex-col">
      <EditorList
        class="shrink-0"
        :active-id="activeId"
        :activated-ids="activatedIds"
        :entries="store.entries"
        @navigate="navigateToEditor"
        @edit="openEditDialog"
        @remove="removeEditor"
        @move-up="moveUp"
        @move-down="moveDown"
      />

      <section class="min-w-0 flex-1 p-2 max-[960px]:pt-0">
        <RouterView v-slot="{ Component }">
          <KeepAlive>
            <component
              :is="Component"
              @create-editor="openCreateDialog"
              @exit-editor="handleExitEditor"
              @activated-change="handleActivatedChange"
            />
          </KeepAlive>
        </RouterView>
      </section>
    </main>

    <EditorFormDialog :entry="editingEntry" :open="editorDialogOpen" @close="closeEditorDialog" @saved="handleSaved" />
    <ImportExportDialog :open="importDialogOpen" @close="importDialogOpen = false" />
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { RouterView, useRoute, useRouter } from 'vue-router';

import AppHeader from './components/AppHeader.vue';
import EditorFormDialog from './components/EditorFormDialog.vue';
import EditorList from './components/EditorList.vue';
import ImportExportDialog from './components/ImportExportDialog.vue';
import { useEditorsStore } from './store/editors';
import type { EditorEntry } from './types/editor-entry';

const route = useRoute();
const router = useRouter();
const store = useEditorsStore();

const editorDialogOpen = ref(false);
const importDialogOpen = ref(false);
const editingEntry = ref<EditorEntry | null>(null);
const activatedIds = ref<string[]>([]);
const activeId = computed(() => (typeof route.params.id === 'string' ? route.params.id : ''));

function openDefaultEntryOnce() {
  if (route.path !== '/' || activeId.value) {
    return;
  }

  const firstIframeEntry = store.entries.find((entry) => entry.openMode === 'iframe');
  if (!firstIframeEntry) {
    return;
  }

  router.replace(`/e/${firstIframeEntry.id}`);
}

onMounted(() => {
  openDefaultEntryOnce();
});

function openCreateDialog() {
  editingEntry.value = null;
  editorDialogOpen.value = true;
}

function openEditDialog(entry: EditorEntry) {
  editingEntry.value = entry;
  editorDialogOpen.value = true;
}

function closeEditorDialog() {
  editorDialogOpen.value = false;
  editingEntry.value = null;
}

function openImportDialog() {
  importDialogOpen.value = true;
}

function navigateToEditor(entry: EditorEntry) {
  if (entry.openMode === 'external') {
    window.open(entry.url, '_blank', 'noopener,noreferrer');
    return;
  }

  router.push(`/e/${entry.id}`);
}

function removeEditor(entry: EditorEntry) {
  activatedIds.value = activatedIds.value.filter((id) => id !== entry.id);
  store.removeEntry(entry.id);
  if (activeId.value === entry.id) {
    router.push('/');
  }
}

function moveUp(entry: EditorEntry) {
  store.moveEntry(entry.id, -1);
}

function moveDown(entry: EditorEntry) {
  store.moveEntry(entry.id, 1);
}

function handleSaved(entry: EditorEntry) {
  closeEditorDialog();
  navigateToEditor(entry);
}

function handleExitEditor() {
  router.push('/');
}

function handleActivatedChange(ids: string[]) {
  activatedIds.value = ids;
}

function exportConfig() {
  const blobUrl = URL.createObjectURL(new Blob([store.exportContent()], { type: 'application/json;charset=utf-8' }));
  const link = document.createElement('a');
  link.href = blobUrl;
  link.download = `editors-${new Date().toISOString().slice(0, 10)}.json`;
  link.click();
  URL.revokeObjectURL(blobUrl);
}

function restoreDefaultConfig() {
  const confirmed = window.confirm('恢复默认将清空当前自定义配置与隐藏设置，是否继续？');
  if (!confirmed) {
    return;
  }

  const reconfirmed = window.confirm('请再次确认：将恢复为系统默认编辑器配置。');
  if (!reconfirmed) {
    return;
  }

  store.resetUserLayer();
  activatedIds.value = [];
  router.push('/');
}
</script>
