/**
 * 解析内置编辑器的 URL，优先级：
 *   1. Vite 环境变量（构建时静态替换，类型见 src/env.d.ts）
 *   2. 默认兜底值（兜底策略由调用方提供，避免 undefined）
 *
 * 设计动机：
 * - 大多数内置入口是公网固定 URL，直接硬编码即可
 * - 自家应用（如 splat-studio）在 dev / staging / prod 各有不同 URL，需要环境区分
 * - 用 `import.meta.env` 而非 `process.env`：浏览器环境标准做法，构建时静态替换，运行时零开销
 * - 用工厂函数包装：业务代码只关心 "拿到 URL"，不关心 "从哪里读"
 *
 * 不直接读 localStorage 的原因：内置默认条目用户可能从未保存过自定义版本，
 * 落到 localStorage 会污染用户数据层；环境差异化属于"构建产物侧"职责。
 */
export function resolveBuiltinUrl(envValue: string | undefined, fallback: string): string {
  const trimmed = envValue?.trim();
  return trimmed && trimmed.length > 0 ? trimmed : fallback;
}
