import type { EditorEntry, EditorExportFile, EditorOpenMode, EditorStorageLayer } from '../types/editor-entry';
import { validateEditorUrl } from './url';

export const EDITOR_STORAGE_KEY = 'viewer-plugin.navigator.editors.v1';
export const EDITOR_EXPORT_VERSION = 1;

const DEFAULT_ALLOW = 'clipboard-read; clipboard-write; fullscreen';

function normalizeOpenMode(mode: unknown): EditorOpenMode {
  return mode === 'external' ? 'external' : 'iframe';
}

export function createEmptyStorageLayer(): EditorStorageLayer {
  return {
    version: EDITOR_EXPORT_VERSION,
    entries: [],
    hiddenBuiltinIds: [],
    orderedIds: [],
  };
}

export function normalizeEditorEntry(candidate: unknown): EditorEntry | null {
  if (!candidate || typeof candidate !== 'object') return null;

  const source = candidate as Partial<EditorEntry>;
  const name = typeof source.name === 'string' ? source.name.trim() : '';
  const url = typeof source.url === 'string' ? validateEditorUrl(source.url).value : '';
  const validation = validateEditorUrl(url);

  if (!source.id || typeof source.id !== 'string' || !name || !validation.valid) return null;

  const createdAt = typeof source.createdAt === 'number' ? source.createdAt : Date.now();
  const updatedAt = typeof source.updatedAt === 'number' ? source.updatedAt : createdAt;

  return {
    id: source.id,
    name,
    url: validation.value,
    openMode: normalizeOpenMode(source.openMode),
    icon: typeof source.icon === 'string' ? source.icon : undefined,
    description: typeof source.description === 'string' ? source.description : undefined,
    sandbox: source.sandbox ?? true,
    allow: typeof source.allow === 'string' && source.allow.trim() ? source.allow : DEFAULT_ALLOW,
    builtin: source.builtin ?? false,
    createdAt,
    updatedAt,
  };
}

export function normalizeStorageLayer(candidate: unknown): EditorStorageLayer {
  if (!candidate || typeof candidate !== 'object') return createEmptyStorageLayer();

  const source = candidate as Partial<EditorStorageLayer>;
  const entries = Array.isArray(source.entries)
    ? source.entries.map(normalizeEditorEntry).filter((entry): entry is EditorEntry => Boolean(entry))
    : [];
  const hiddenBuiltinIds = Array.isArray(source.hiddenBuiltinIds)
    ? source.hiddenBuiltinIds.filter((id): id is string => typeof id === 'string')
    : [];
  const orderedIds = Array.isArray(source.orderedIds)
    ? source.orderedIds.filter((id): id is string => typeof id === 'string')
    : [];

  return {
    version: EDITOR_EXPORT_VERSION,
    entries,
    hiddenBuiltinIds,
    orderedIds,
  };
}

export function loadEditorStorage(): EditorStorageLayer {
  if (!globalThis.localStorage) return createEmptyStorageLayer();

  const rawValue = globalThis.localStorage.getItem(EDITOR_STORAGE_KEY);
  if (!rawValue) return createEmptyStorageLayer();

  try {
    return normalizeStorageLayer(JSON.parse(rawValue));
  } catch (error) {
    console.error('读取编辑器导航配置失败，已回退为空配置。', error);
    return createEmptyStorageLayer();
  }
}

export function saveEditorStorage(layer: EditorStorageLayer): void {
  if (!globalThis.localStorage) return;
  globalThis.localStorage.setItem(EDITOR_STORAGE_KEY, JSON.stringify(normalizeStorageLayer(layer)));
}

export function parseEditorExport(content: string): EditorExportFile {
  const parsed = JSON.parse(content) as EditorExportFile;
  const layer = normalizeStorageLayer(parsed);

  return {
    version: EDITOR_EXPORT_VERSION,
    entries: layer.entries,
    hiddenBuiltinIds: layer.hiddenBuiltinIds,
    orderedIds: layer.orderedIds,
  };
}

export function serializeEditorExport(layer: EditorStorageLayer): string {
  const normalizedLayer = normalizeStorageLayer(layer);
  const exportFile: EditorExportFile = {
    version: EDITOR_EXPORT_VERSION,
    entries: normalizedLayer.entries,
    hiddenBuiltinIds: normalizedLayer.hiddenBuiltinIds,
    orderedIds: normalizedLayer.orderedIds,
  };

  return JSON.stringify(exportFile, null, 2);
}
